import csv,sqlite3
conn=sqlite3.connect('db/transactions_1k.db')
curs=conn.cursor()
curs.execute('SELECT DISTINCT CustomerID FROM transactions_1k WHERE ProductID=5 AND Price > 29.0 AND Date LIKE "2012-08-%"')
custs={r[0] for r in curs.fetchall()}
conn.close()
cust_cons={}
for row in csv.DictReader(open('csv/yearmonth.csv')):
    if row['Date']=='201208' and int(row['CustomerID']) in custs:
        cust_cons[int(row['CustomerID'])]=row['Consumption']
for c in list(cust_cons.items())[:5]: print(c)

